for(var ii=0;ii<tabs.length;ii++){
    tabs[ii].addEventListener('click', function(e){
        e.preventDefault();
        this.parentElement.parentElement.querySelector('.active').classList.remove('active');
        this.parentElement.classList.add('active');
        
		var tabId = this.getAttribute('data-match');
		var tabSelector = document.querySelector('[data-go="'+tabId+'"]');
		var tabHref = this.getAttribute('href');
		
		if(tabSelector != null) {
			tabSelector.scrollIntoView({
			  behavior: 'smooth'
			});
		}
		
		if(tabHref == "#recent") switchTabs(tabHref);
		else switchTabs("#people");
    });
}

function switchTabs(tabId){
    var tabPanes = document.querySelectorAll('.tab-content .tab-pane');
    for(var j =0;j<tabPanes.length;j++){
        tabPanes[j].classList.remove('in','active');
        if(tabPanes[j].getAttribute('id') == tabId)
            tabPanes[j].classList.add('in','active');
    }
    document.querySelector(tabId).classList.add('in','active');
}

