function fillSearchedEmojis(search){
	$('#people .emo-list').empty();
	
	emojicat.reduce( (p, _, i) => 
	p.then(_ => new Promise(resolve =>
			setTimeout(function () {
				insertEmoList2(ALL.filter(function (el) { return el.cat == emojicat[i] && el.enable == 0 && el.desc.indexOf(search) !== -1; }),'#people'); 
				resolve();
			}, i * 10)
		))
	, Promise.resolve() );
}

function fillAllEmojis(){
	$('#people .emo-list').empty();
	
	emojicat.reduce( (p, _, i) => 
	p.then(_ => new Promise(resolve =>
			setTimeout(function () {
				insertEmoList2(ALL.filter(function (el) { return el.cat == emojicat[i] && el.enable == 0; }),'#people'); 
				resolve();
			}, i * 10)
		))
	, Promise.resolve() );
}

function insertEmoji(emo){
    var input = document.querySelector("#emoji-output");
	input.value+=emo;
	
	copyToClipboard(emo);
	toastr.options = { "positionClass": "toast-bottom-center", "timeOut": "2000", "progressBar": "true", "closeButton" : "true", "extendedTimeOut": "1000"};
	toastr.info("Copied to clipboard!");
}

function copyEmoji(){
    var input = document.querySelector("#emoji-output");
    if(input.value.length > 0){
        copyToClipboard(input.value);
		toastr.options = { "positionClass": "toast-bottom-center", "timeOut": "2000", "progressBar": "true", "closeButton" : "true", "extendedTimeOut": "1000"};
		toastr.info("Copied to clipboard!");
    }
}

function executeScriptClickemoji(clickemoji) {
	document.querySelectorAll('#configEmoji').forEach(el => el.remove());
	var target = document.querySelector("body");
	var newContent = '<div id="configEmoji">'+clickemoji+'<\/div>';
	target.insertAdjacentHTML('beforeend', newContent);
}

function click(value){
	chrome.tabs.query({
		active: true, currentWindow: true
	}, async function(tabs) {
	chrome.scripting.executeScript({target: {tabId: tabs[0].id, allFrames: true},	func: executeScriptClickemoji, args: [value]}, function(results) {
		if (results === undefined || results[0] === undefined) {
			// Fire error handling code
			// Send to background
			chrome.runtime.sendMessage({ clickemoji: value }, function (response) { });
		} else {
			// null here on the tabId means the last active tab opened in the browser
			chrome.scripting.executeScript({target: {tabId: tabs[0].id, allFrames: true},	files: ['content-emoji.js']});
		}
	});
});
}

function insertEmoList2(src, selector){
    var emoList = document.querySelector(selector).querySelectorAll('.emo-list')[0];

	var category = '';
	var domManipulation = '';
	
    for(var i=0;i<src.length;i++){
		if(src[i].cat != category) {
			category = src[i].cat;
			domManipulation += "<li data-go='" + category + "' style='width: 100%; height: auto; font-weight: 600;'>" + category + "</li>";
		}

		var transformedStr = src[i].code.split(' ').map(code => `&#x${code};`).join('');
		domManipulation += "<li data-id='"+src[i].id+"' class='emoji raw"+(selector == '#recent' ? ' emoji-recent' : '')+"' data-value='" + src[i].code + "' title='"+src[i].desc+"'>"+ transformedStr +"</li>";
    }
	emoList.innerHTML += domManipulation;
}

function insertEmoList(src, selector){
    var emoList = document.querySelector(selector).querySelectorAll('.emo-list')[0];
	if(selector == "#recent") emoList.innerHTML = ""; 
	
	var domManipulation = '';
    for(var i=0;i<src.length;i++){
        var transformedStr = src[i].split(' ').map(code => `&#x${code};`).join('');
        domManipulation += "<li class='emoji raw"+(selector == '#recent' ? ' emoji-recent' : '')+"' data-value='" + src[i] + "'>"+transformedStr+"</li>";
    }
	
	emoList.innerHTML += domManipulation;
}

var copyToClipboard = function(text){
    var textArea = document.createElement("input");

    // Place in top-left corner of screen regardless of scroll position.
    textArea.style.position = 'fixed';
    textArea.style.top = 0;
    textArea.style.left = 0;

    // Ensure it has a small width and height. Setting to 1px / 1em
    // doesn't work as this gives a negative w/h on some browsers.
    textArea.style.width = '2em';
    textArea.style.height = '2em';

    // We don't need padding, reducing the size if it does flash render.
    textArea.style.padding = 0;

    // Clean up any borders.
    textArea.style.border = 'none';
    textArea.style.outline = 'none';
    textArea.style.boxShadow = 'none';

    // Avoid flash of white box if rendered for any reason.
    textArea.style.background = 'transparent';


    textArea.value = text;

    document.body.appendChild(textArea);

    textArea.select();

    try {
        var successful = document.execCommand('copy');
        var msg = successful ? 'successful' : 'unsuccessful';
        console.log('Copying text command was ' + msg);
    } catch (err) {
        console.log('Oops, unable to copy');
    }

    document.body.removeChild(textArea);
}

$.fn.isInViewport = function() {
    var elementTop = $(this).offset().top;
    var elementBottom = elementTop + $(this).outerHeight();

    var viewportTop = $(window).scrollTop();
    var viewportBottom = viewportTop + $(window).height();

    return elementBottom > viewportTop && elementTop < viewportBottom;
};

