/*** Introjs firstRun and show tutorial ***/
function startTutorial() {
	var intro = introJs();
	var steps = [
			{element: '#people [data-value="1F600"]',intro: 'Copy/paste any emoji',position: 'bottom'},
			{element: '.round-tabs.two',intro: 'Emoji Categories.',position: 'bottom'},
			{element: '#emoji-search',intro: 'Search for Emojis here - English only!',position: 'bottom'},
			{element: '#emoji-output',intro: 'Text input. All selected emoji will show here. Use it to copy/paste emojis.',position: 'top'},
			{element: '#copy',intro: 'Copy all emojis on that left input box.',position: 'left'},
			{element: '#newSettings',intro: 'Settings - Mini Tutorial - Premium.',position: 'left'},
			{element: '#newWindow',intro: 'Pop out this window.',position: 'left'}
	];
	steps = steps.filter(function (obj) { return $(obj.element).length; });
	steps.unshift({title: i18n.get("introjs-welcome"), intro: 'Click on any emoji and it will be copied to Clipbard. Paste it (ctrl + v) on any input field on any app/site/software and the emoji will show.'});
	steps.push({title: i18n.get("introjs-welcome"), intro: i18n.get("introjs-end")});
	intro.setOptions({ steps: steps });
	intro.onafterchange(function(targetElement) {
		switch (targetElement.id){
			case "copy":
				return;
			break;
			case "newSettings":
				return;
			break;
			case "newWindow":
				return;
			break;
		}
		switch (targetElement.localName){
			case "li":
				$('#people [data-value="1F600"]').click();
			break;
			case "span":
				var tabSelector = document.querySelector('[data-go="Animals & Nature"]');
				if(tabSelector != null) {
					tabSelector.scrollIntoView({
					  behavior: 'smooth'
					});
				}
			break;
		}
	});
	intro.start();
}

$(function() {
	$.contextMenu({
		selector: '.emoji-recent', 
		callback: function(key, options) {
			var emoji = options.$trigger[0];
			var found = -1;
			for(i in FRENQUENT){
				if(FRENQUENT[i] == emoji.dataset.value){
					found = parseInt(i);
					break;
				}
			}
			if(parseInt(found) >= 0){
				FRENQUENT.splice(found, 1);
				localStorage.setItem("web.settings.frequentlyUsed", JSON.stringify(FRENQUENT));
				insertEmoList(FRENQUENT,'#recent');
			}
		},
		items: {
			"delete": {name: "Delete", icon: "delete"}
		}
	}); 
});

$(function() {
	$.contextMenu({
		selector: '#newSettingsButton', 
		trigger: 'left',
		callback: function(key, options) {
			if(key == "about"){
				chrome.tabs.create({url: chrome.runtime.getURL("options/index.html")});
			} else if (key == "tutorial") {
				startTutorial();
			} else if (key == "premium") {
				chrome.tabs.create({url: chrome.runtime.getURL("options/indexPremium.html")});
			} else if (key == "rate") {
				chrome.tabs.create({url: "https://microsoftedge.microsoft.com/addons/detail/" + chrome.runtime.id });
			} else if (key == "news") {
				clickInformationNews();
			} else if (key == "share") {
				clickSocialMedia();
			}
		},
		items: {
			"about": {name: "About", icon: "settings"},
			"tutorial": {name: "Mini Tutorial", icon: "tutorial"},
			"premium": {name: "Premium", icon: "premium"},
			"rate": {name: "Rate us 5 \u2764", icon: "star"},
			"share": {name: "Share", icon: "share"},
			"news": {name: "Tips - Tricks - News", icon: "info"}
		}
	}); 
});


